from collections import Counter

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = Counter(v for row in g for v in row)
    bg = counts.most_common(1)[0][0]

    # Runs painted along the four outer edges are the ray launch bars.
    runs = []
    # Each run is (edge, start, end, marker); end is exclusive.
    for c in range(w):
        pass
    for edge, seq in [('top', g[0]), ('bottom', g[-1]),
                      ('left', [g[r][0] for r in range(h)]),
                      ('right', [g[r][-1] for r in range(h)])]:
        i = 0
        while i < len(seq):
            v = seq[i]
            j = i + 1
            while j < len(seq) and seq[j] == v:
                j += 1
            if v != bg and j - i >= 2:
                runs.append((edge, i, j, v))
            i = j
    if not runs:
        return g
    marker_colors = {v for _,_,_,v in runs}
    other = [(v,n) for v,n in counts.items() if v != bg and v not in marker_colors]
    if not other:
        return g
    ray_color = max(other, key=lambda x:x[1])[0]
    points = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == ray_color]

    # Pick the bar whose span contains the largest share of point coordinates;
    # their offsets are copied to the matching bars on the opposing edges.
    orientations = [('top','bottom', 1), ('left','right', 0)]
    selected = []
    for edge_a, edge_b, axis in orientations:
        group = [run for run in runs if run[0] in (edge_a, edge_b)]
        if not group:
            continue
        candidates=[]
        for run in group:
            _, start, end, marker = run
            offsets = sorted({(c if axis else r)-start for r,c in points
                              if start <= (c if axis else r) < end})
            if offsets:
                candidates.append((len(offsets), run, offsets))
        if not candidates:
            continue
        _, ref, offsets = max(candidates, key=lambda x:x[0])
        marker=ref[3]
        for run in group:
            if run[3] == marker:
                selected.append((run, offsets, axis))

    if not selected:
        return g
    for (edge,start,end,marker), offsets, axis in selected:
        corner_capped = (edge == 'top' and 0 in {start + off for off in offsets})
        for off in offsets:
            k = start + off
            if k >= end:
                continue
            if edge == 'top':
                r,c,dr,dc = 0,k,1,0
                # A corner lane at the far-left edge stops before the opposite border.
                limit = h - 1 if corner_capped else h
                rr = 1
                while rr < limit:
                    if g[rr][c] == ray_color:
                        g[rr][c] = 4
                        break
                    g[rr][c] = ray_color
                    rr += 1
            elif edge == 'bottom':
                c=k
                rr=h-2
                while rr >= 0:
                    if g[rr][c] == ray_color:
                        g[rr][c] = 4
                        break
                    g[rr][c] = ray_color
                    rr -= 1
            elif edge == 'left':
                r=k
                cc=1
                while cc < w:
                    if g[r][cc] == ray_color:
                        g[r][cc] = 4
                        break
                    g[r][cc] = ray_color
                    cc += 1
            else: # right
                r=k
                cc=w-2
                while cc >= 0:
                    if g[r][cc] == ray_color:
                        g[r][cc] = 4
                        break
                    g[r][cc] = ray_color
                    cc -= 1
    return g
